// Schema do Pacote de Conteúdo (Gerado por IA ou Carregado do Banco Padrão)
export const PacoteConteudoExp03Schema = z.object({
  indicadorNome: z.string().min(3).max(60),
  unidadeMedida: z.string().min(1).max(20),
  serieHistorica: z.array(z.object({
    periodo: z.string().min(1).max(20),
    valor: z.number().min(0).max(100)
  })).length(4),
  notaMetodologica: z.object({
    orgaoEmissor: z.string().min(3).max(80),
    tituloDocumento: z.string().min(3).max(80),
    textoExplicativo: z.string().min(20).max(400)
  }),
  reacoesComunitarias: z.object({
    zero: z.array(z.object({
      autor: z.string().min(2).max(40),
      cargoOuPerfil: z.string().min(2).max(40),
      mensagem: z.string().min(2).max(180)
    })).length(3),
    oitenta: z.array(z.object({
      autor: z.string().min(2).max(40),
      cargoOuPerfil: z.string().min(2).max(40),
      mensagem: z.string().min(2).max(180)
    })).length(3)
  })
});
export type PacoteConteudoExp03 = z.infer<typeof PacoteConteudoExp03Schema>;

