  /* Botões e Alvos Táteis (Mínimo 64x64px ou vãos amplos >= 16px) */
  .btn-alvo-64 {
    min-height: 64px;
    min-width: 64px;
    padding: 12px 16px;
    border-radius: 8px;
    font-size: 14px;
    font-weight: 700;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
