  .tabela-zoom th, .tabela-zoom td {
    padding: 12px 14px;
  }

  /* Cards de Anexo */
  .card-anexo {
    display: flex;
    align-items: center;
    gap: 16px;
    padding: 12px;
    background-color: var(--superficie-base);
    border: 1px solid var(--borda-padrao);
    border-radius: 8px;
    cursor: pointer;
    min-height: 64px;
  }

  .card-anexo-icone {
    width: 44px;
    height: 48px;
    background-color: var(--superficie-midia);
    border: 1px solid var(--borda-padrao);
    border-radius: 4px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 10px;
    font-weight: 700;
    flex-shrink: 0;
  }

  /* Gráficos Vetoriais SVG */
  .grafico-box {
    background-color: var(--superficie-base);
    border: 1px solid var(--borda-padrao);
    border-radius: 6px;
    padding: 8px;
