  /* Barra de Composição */
  .unoo-composer {
    background-color: var(--superficie-elevada);
    border-top: 1px solid var(--borda-padrao);
    padding: 16px;
    display: flex;
    flex-direction: column;
    gap: 16px;
    flex-shrink: 0;
  }

  /* Modais e Banners Fixos */
  .banner-fixo {
    padding: 14px 16px;
    background-color: var(--superficie-elevada);
    border-top: 2px solid var(--borda-foco);
    font-size: 13px;
    font-weight: 600;
    text-align: center;
    line-height: 1.4;
    color: var(--texto-primario);
  }

  .modal-backdrop {
    position: absolute;
    inset: 0;
    background-color: var(--texto-primario);
    opacity: 0.85;
    z-index: 45;
  }

  .modal-dialog {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    background-color: var(--superficie-base);
    border: 3px solid var(--borda-foco);
    border-radius: 12px;
    padding: 24px;
    max-width: 340px;
    width: calc(100% - 40px);
    display: flex;
    flex-direction: column;
    gap: 16px;
    z-index: 50;
  }

  /* BottomSheet / AttachmentSheet */
  .bottom-sheet {
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    background-color: var(--superficie-base);
    border-top: 3px solid var(--borda-foco);
    border-top-left-radius: 20px;
    border-top-right-radius: 20px;
    padding: 20px;
    max-height: 85%;
    overflow-y: auto;
    display: flex;
    flex-direction: column;
    gap: 16px;
    z-index: 40;
    box-shadow: 0 -10px 25px rgba(0,0,0,0.2);
  }

  .bottom-sheet-grabber {
    width: 48px;
    height: 4px;
    background-color: var(--borda-padrao);
    border-radius: 2px;
    align-self: center;
    margin-bottom: 4px;
  }

  /* Interface do Professor (Unooria Hub Desktop) */
  .hub-container {
    display: flex;
    flex-direction: column;
    height: 100%;
    background-color: var(--superficie-elevada);
  }

  .hub-header {
    height: 60px;
    background-color: var(--superficie-base);
    border-bottom: 1px solid var(--borda-padrao);
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0 24px;
  }

  .hub-corpo {
    flex: 1;
    padding: 24px;
    overflow-y: auto;
    display: flex;
    flex-direction: column;
    gap: 20px;
  }

  .hub-card {
    background-color: var(--superficie-base);
    border: 1px solid var(--borda-padrao);
    border-radius: 8px;
    padding: 20px;
    display: flex;
    flex-direction: column;
    gap: 14px;
  }

  .hub-card.foco {
    border: 2px solid var(--borda-foco);
  }

  .form-group {
    display: flex;
    flex-direction: column;
    gap: 6px;
  }

  .form-label {
    font-size: 13px;
    font-weight: 700;
    color: var(--texto-primario);
  }

  .form-input, .form-textarea, .form-select {
    padding: 10px 12px;
    border: 1px solid var(--borda-padrao);
    border-radius: 4px;
    font-size: 14px;
    background-color: var(--superficie-base);
    color: var(--texto-primario);
    width: 100%;
  }

  .form-input:focus, .form-textarea:focus, .form-select:focus {
    outline: none;
    border: 2px solid var(--borda-foco);
  }

  /* Anotação interna obrigatória de estado */
  .rotulo-estado-interno {
    position: absolute;
    bottom: 4px;
