  let grupoAtual = '';
  quadros.forEach((q, idx) => {
    const etapa = q.getAttribute('data-etapa');
    const screenId = q.getAttribute('data-screen-id');
    const estado = q.getAttribute('data-estado');
    const ator = q.getAttribute('data-ator');
