    const item = document.createElement('button');
    item.className = `trilho-item ${idx === 0 ? 'ativo' : ''}`;
    item.setAttribute('data-idx', idx);
    item.innerHTML = `
      <div class="trilho-item-cabecalho">
        <span class="trilho-item-id">${screenId}</span>
        <span class="trilho-item-ator">${ator}</span>
