    `;
    item.addEventListener('click', () => navegarPara(idx));
    trilho.appendChild(item);
  });

  function atualizarTela() {
    quadros.forEach((q, idx) => {
      if (idx === indiceAtual) {
        q.classList.add('tela-ativa');
      } else {
        q.classList.remove('tela-ativa');
      }
    });

    const ativa = quadros[indiceAtual];
    const screenId = ativa.getAttribute('data-screen-id');
    const estado = ativa.getAttribute('data-estado');
    const etapa = ativa.getAttribute('data-etapa');
    const ator = ativa.getAttribute('data-ator');
    const titulo = ativa.getAttribute('data-titulo') || screenId;
    const acao = ativa.getAttribute('data-acao') || '—';
    const muda = ativa.getAttribute('data-muda') || '—';

    // Barra de topo
    document.getElementById('topo-etapa').textContent = `${etapa} · ${ator === 'PROF' ? 'Docente' : 'Estudante'}`;
    document.getElementById('topo-titulo').textContent = `${screenId} · ${titulo} (${estado})`;
    document.getElementById('topo-contador').textContent = `${indiceAtual + 1} / ${quadros.length}`;

    // Marcas especiais
    const marcaEl = document.getElementById('topo-marca');
    if (screenId === 'E4-ALU-02') {
      marcaEl.style.display = 'inline-block';
      marcaEl.className = 'topo-marca';
      marcaEl.textContent = 'PICO / AHA';
    } else if (screenId === 'E4-ALU-03' || screenId === 'E4-PROF-01') {
      marcaEl.style.display = 'inline-block';
      marcaEl.className = 'topo-marca gate';
      marcaEl.textContent = 'GATE / TRAVA';
    } else {
      marcaEl.style.display = 'none';
    }

    // Botões de navegação
    document.getElementById('btn-ant').disabled = indiceAtual === 0;
    document.getElementById('btn-prox').disabled = indiceAtual === quadros.length - 1;

    // Atualizar trilho
    const itensTrilho = trilho.querySelectorAll('.trilho-item');
    itensTrilho.forEach((it, idx) => {
      if (idx === indiceAtual) {
        it.classList.add('ativo');
        it.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
      } else {
        it.classList.remove('ativo');
      }
    });

    // Legenda da Moldura
    const legendaMoldura = document.getElementById('legenda-moldura');
    if (ativa.classList.contains('moldura-mobile')) {
      legendaMoldura.textContent = 'casca de aparelho 375×812 dentro do hub';
    } else {
      legendaMoldura.textContent = 'janela do hub, 1366×768';
    }

    // Painel de Produto
    const infoEtapa = TEXTOS_ETAPA[etapa] || TEXTOS_ETAPA["E0"];
    document.getElementById('painel-rotulo').textContent = infoEtapa.rotulo;
    document.getElementById('painel-titulo').textContent = infoEtapa.titulo;
    document.getElementById('painel-corpo').textContent = infoEtapa.texto;
    document.getElementById('painel-fonte').textContent = `Fonte: ${infoEtapa.fonte}`;

    // Rodapé de Metadados
    document.getElementById('rodape-tela').textContent = `${screenId} (${estado})`;
    document.getElementById('rodape-acao').textContent = acao;
    document.getElementById('rodape-muda').textContent = muda;
  }

  function navegarPara(idx) {
    if (idx >= 0 && idx < quadros.length) {
      indiceAtual = idx;
      atualizarTela();
    }
  }

  document.getElementById('btn-ant').addEventListener('click', () => navegarPara(indiceAtual - 1));
  document.getElementById('btn-prox').addEventListener('click', () => navegarPara(indiceAtual + 1));

  // Navegação por teclado
  window.addEventListener('keydown', (e) => {
    if (e.key === 'ArrowRight' || e.key === 'Right') {
      navegarPara(indiceAtual + 1);
    } else if (e.key === 'ArrowLeft' || e.key === 'Left') {
      navegarPara(indiceAtual - 1);
    }
  });

  // Mapeamento de cliques em botões dentro dos quadros para avanço de demo
  document.querySelectorAll('.acao-avancar').forEach(btn => {
    btn.addEventListener('click', () => navegarPara(indiceAtual + 1));
  });

  document.querySelectorAll('.acao-voltar').forEach(btn => {
    btn.addEventListener('click', () => navegarPara(indiceAtual - 1));
  });

  document.querySelectorAll('.acao-atalho-padrao').forEach(btn => {
    btn.addEventListener('click', () => {
      const idxAtivacao = quadros.findIndex(q => q.getAttribute('data-screen-id') === 'E0-PROF-05' && q.getAttribute('data-estado') === 'ativado');
      if (idxAtivacao !== -1) navegarPara(idxAtivacao);
