      if (idx429 !== -1) navegarPara(idx429);
    });
  });

  document.querySelectorAll('.acao-zoom').forEach(btn => {
    btn.addEventListener('click', () => {
      const telaAtual = quadros[indiceAtual];
      if (telaAtual.getAttribute('data-estado') === 'normal') {
        const idxZoom = quadros.findIndex(q => q.getAttribute('data-screen-id') === 'E2-ALU-01' && q.getAttribute('data-estado') === 'zoom acessível ativo [D0-1]');
        if (idxZoom !== -1) navegarPara(idxZoom);
      } else {
        const idxNorm = quadros.findIndex(q => q.getAttribute('data-screen-id') === 'E2-ALU-01' && q.getAttribute('data-estado') === 'normal');
        if (idxNorm !== -1) navegarPara(idxNorm);
      }
    });
  });

  document.querySelectorAll('.acao-abrir-pdf').forEach(card => {
    card.addEventListener('click', () => {
      const idxSheet = quadros.findIndex(q => q.getAttribute('data-screen-id') === 'E2-ALU-02');
      if (idxSheet !== -1) navegarPara(idxSheet);
    });
  });

  document.querySelectorAll('.acao-selecionar-80').forEach(btn => {
    btn.addEventListener('click', () => {
      const idx80 = quadros.findIndex(q => q.getAttribute('data-screen-id') === 'E2-ALU-03' && q.getAttribute('data-estado') === 'selecionado');
      if (idx80 !== -1) navegarPara(idx80);
    });
  });

  document.querySelectorAll('.acao-marcar-b').forEach(input => {
    input.addEventListener('change', () => {
      const idxSin = quadros.findIndex(q => q.getAttribute('data-screen-id') === 'E6-ALU-01' && q.getAttribute('data-estado') === 'sinalização ativa');
      if (idxSin !== -1) navegarPara(idxSin);
    });
  });

  document.querySelectorAll('.acao-ver-fonte').forEach(btn => {
    btn.addEventListener('click', () => {
      const idxSheet = quadros.findIndex(q => q.getAttribute('data-screen-id') === 'E6-ALU-02');
      if (idxSheet !== -1) navegarPara(idxSheet);
    });
  });

  document.querySelectorAll('.acao-pular').forEach(btn => {
    btn.addEventListener('click', () => {
      const telaAtual = quadros[indiceAtual];
      const etapa = telaAtual.getAttribute('data-etapa');
      if (etapa === 'E4b') {
        const idxE5 = quadros.findIndex(q => q.getAttribute('data-screen-id') === 'E5-ALU-01' && q.getAttribute('data-estado') === 'normal');
        if (idxE5 !== -1) navegarPara(idxE5);
      } else if (etapa === 'E6') {
        const idxE6Concl = quadros.findIndex(q => q.getAttribute('data-screen-id') === 'E6-ALU-03');
        if (idxE6Concl !== -1) navegarPara(idxE6Concl);
      }
    });
  });

  // Slider de calibração interativa na E5
  const slider = document.getElementById('slider-eixo');
  if (slider) {
    slider.addEventListener('input', (e) => {
      // Interatividade exploratória livre
    });
  }

  // Inicialização
  atualizarTela();
</script>
</body>
</html>
